-- Built-in manual. English keys are localized; IDs and navigation targets stay stable.
local _, ns = ...
local L = ns.Badb.L
ns.Badb.HelpData = { sections = {
    { id = "start", title = L["Start here"], text = L["Welcome to BadbUI, a modular interface for WoW: Forever. This manual is available inside the addon without a website or internet connection. Guild synchronization needs the companion and its server.\n1. Type /badb (or /bui) to open settings. Use the sidebar or the search field to find a page or option.\n2. Run /badb setup for guided setup. Choose your content and role, review the changes, then apply. Confirm the role yourself if detection is uncertain.\n3. Open Home to turn individual modules on or off. Open a module's options to customize it.\n4. Create a backup before making large changes. Use the Help topics below whenever you need a reference.\nUse the Topic menu to read one subject, choose All topics for the complete manual, or search to find text across every topic."] , page = "home", guide = "starter:primo-avvio" },
    { id = "language", title = L["Language and worldwide use"], text = L["Open Appearance > Language, or type /badb language enUS for English, /badb language itIT for Italian, or /badb language auto to follow the client. Apply a change with /reload. The preference applies to the whole addon, across profiles.\nAutomatic mode uses Italian on an Italian client and English on all other clients, including enGB. English and Italian are the supported interface languages; other client languages currently use English.\nSlash commands, module IDs and saved profile data stay the same in both languages. Your own profile names, scripts, guild posts and server content are shown as written by their authors.\nThe built-in macro catalog and spell names remain in English. On a non-English game client, check the localized spell names before using a macro; changing the interface language does not translate the game or its spells. The macro command help documents individual spell-name overrides."] , page = "appearance" },
    { id = "profiles", title = L["Profiles, presets and backups"], text = L["Profiles keep separate module settings and frame layouts. In Profiles you can create, copy, rename, switch, import, export or delete a profile. You can also assign profiles to talent groups where the client supports them. /badb profile lists profiles; /badb profile <name> selects one.\nPresets provide starting layouts for class, role, PvE and PvP. Read the preview before applying. The preset workflow creates a backup and normally a new profile. /badb undo reverts the last preset operation when its previous profile still exists.\nBackups are saved snapshots for recovery. Create one before experimenting, then restore or export it from Backups. Profile export and backup export have different scopes: read the import preview before applying either one.\nImport / Export lets you copy a full profile or one module's options. Copy the complete generated string. Importing settings does not install other addons or create profiles inside unsupported integrations."] , page = "profiles", guide = "starter:profili-preset" },
    { id = "layout", title = L["Move frames and customize the look"], text = L["Use Appearance to change the theme, accent, background opacity and settings-window scale. Scaling controls the game UI scale. ElvUI Style applies a coordinated look; review its changes and backup first.\nType /badb unlock to move supported frames, then use it again to lock them. Drag to move; use the arrow keys and Shift + mouse wheel where the mover supports them. Layout Studio adds selection, alignment, spacing and undo/redo tools.\nBlizzard frames managed by Edit Mode must use the client-supported layout controls. Edit Mode Bridge saves and reapplies the supported layout with a profile. Some built-in layouts must be duplicated in Edit Mode before they can be edited.\nIf a frame cannot move or resize, check its module, the active profile, combat state and Edit Mode support. Avoid having two addons control the same frame."] , page = "LayoutStudio", guide = "starter:layout-edit-mode" },
    { id = "macros", title = L["Macro catalog: class, specialization, PvE and PvP"], text = L["Open Macros with /badb macro. Choose Class, Specialization and Content to browse shared, PvE and PvP entries. Read Code and the notes before turning a macro on: a listed spell may need a talent, training or a specific client feature.\nTurn on creates the macro in the game's /macro panel. Pick up puts an active macro on your cursor so you can drag it onto an action bar. Press that action-bar button yourself to execute it. Turning on a catalog entry does not automatically play your character.\nTurn off removes an unchanged macro created by BadbUI. A user macro with the same name is never overwritten, and a catalog macro edited by hand is kept. Disabling the Macros module does not delete created macros.\nSlots are limited: enable only the entries you need. Creation and editing are unavailable in combat. Custom bodies must fit the engine's 255-character limit and names its 16-character limit. The client may expose different slot capacities.\nUse /badb macro list <spec> pve (or pvp), /badb macro show <name>, /badb macro on <name>, /badb macro off <name>. /badb macro alloff requests removal of all unchanged managed macros; use it intentionally.\nMacro bodies remain in English. Catalog entries have not been verified inside the Forever client; check abilities, conditionals and focus/arena units in game before relying on them."] , page = "Macros" },
    { id = "contexts", title = L["Automatic profiles and other addons"], text = L["Contexts can switch profiles using rules for content, instance, class, role, specialization or group. Check rule priority and whether automatic switching is enabled. A manual profile change can suspend switching. Inspect the current context before changing a rule.\nIntegrations can capture and reapply supported settings from installed addons. Support differs by addon; some adapters only report status. Read the status and warnings before Apply or Reset. The other addon must be installed and its required profile must exist.\nIf settings keep changing unexpectedly, check Contexts, specialization assignments and integrations. For conflicts, choose one addon to control each set of bars, frames or nameplates."] , page = "Contexts", guide = "starter:regole-contesto" },
    { id = "scripts", title = L["Scripts and automation"], text = L["The script editor manages your own Lua snippets with manual, login, event or timer triggers. Read the code before enabling or importing a script. Use clear names and test one script at a time.\nScripts use the addon environment and remain subject to the client's protected-action and combat restrictions. Repeated script errors can stop a script automatically. Use Stop or turn the script off, then inspect its error and the addon log.\nScripts, imported code and macro bodies are not translated when you change the interface language. The editor and command help explain the supported triggers and controls."] , page = "Scripts" },
    { id = "guild", title = L["Guild and companion"], text = L["The guild panel shows the server snapshot: raid calendar, signups, weekly availability, tactics, guild news, guides and armory. These features need a connected companion; the interface modules and local manual work without it.\nInstall the companion and link the addon code from your website profile. Use /badb guildscan to refresh your character snapshot, then /reload to write SavedVariables for the companion. Wait for the companion to finish, then /reload again to load the updated server snapshot.\nGuild answers are queued locally and sent through the companion. If data looks old, check the snapshot time and pending actions, then the companion's connection. Server text remains in the author's language. Tactical ratings are officer assessments, not official combat statistics."] },
    { id = "guides", title = L["Guides and learning"], text = L["Open the guide library with /badb guide. Search by keyword, filter categories and save useful entries with the bookmark star. Guides can include steps whose completion you track, links to copy and zone-based suggestions.\nThe starter library covers setup, profiles, class templates, Edit Mode, sharing, integrations, client restrictions, roles, PvE, PvP and troubleshooting. Use a topic's Read guide button for a deeper explanation.\nGuide titles and built-in text follow the addon language. Content marked uncertain still needs in-game verification; a translated guide does not confirm a game mechanic. Imported guides and linked websites may use other languages."] , page = "Guides", guide = "starter:usare-guide" },
    { id = "troubleshooting", title = L["Troubleshooting and recovery"], text = L["Cannot change a setting? Leave combat and try again. Check that the module is on, that you are editing the intended profile, and that the client exposes the required API.\nSomething disappeared? Check Hider, module visibility and the active profile. Unlock supported frames to find misplaced elements. Restore a backup if needed; avoid resetting everything as your first step.\nUnexpected appearance or repeated changes? Check for another UI addon controlling the same elements, Contexts rules and specialization profile assignments.\nMacro does not work? Check the spell name in the game client, learned abilities and talents, valid target/focus, macro notes, combat state and free slots. Turn on only creates it; you must place and press it on a bar.\nRun /badb doctor run for checks. /badb doctor report opens a report you can copy, /badb doctor errors shows captured errors, and /badb log shows recent addon messages. Review a report before sharing it; include your client build, addon version and exact steps to reproduce the issue.\nRestore a known backup or use /badb undo for the last preset where available. /reload restarts the interface and applies a pending language change."] , page = "Diagnostics", guide = "starter:problemi-comuni" },
    { id = "limits", title = L["Client compatibility and limits"], text = L["BadbUI targets WoW: Forever. Available APIs and protected actions depend on the game client. Some features may be unavailable, deferred until combat ends, or require in-game verification.\nSecret values cannot be safely inspected like ordinary Lua data. Addon scripts cannot bypass protected actions, combat restrictions or unavailable combat-log APIs. Role detection can be uncertain; use /badb role <tank|healer|dps|auto> when you need to confirm or clear a role override.\nBuilt-in UI translations support English and Italian. This does not imply verified compatibility with every localized game client. Macro spell names stay in English by default, and guild content keeps its original language."], guide = "starter:restrizioni-addon" },
    { id = "chatbot", title = L["Chatbot and character assistance"], text = L["Open Chatbot with /badb chat. Start the local nikcli embedded runtime, then use Check replies to load providers and models. Choose a connected provider, a model and the available reasoning option.\nWrite a question, attach relevant quests with Add quests and choose whether to include bags. Level and zone are included automatically. Send & reload saves the question and character snapshot; wait for Reply ready in the local runtime, then use Check replies to reload and read the answer.\nSettings lets you connect a provider with an API key or a supported OAuth method, refresh the model catalog and adjust advanced nikcli configuration. Keys entered in game pass through local SavedVariables until acknowledged and reloaded; do not share those files or their backups.\nQuestions and replies belong to the current character. New chat clears that character's conversation once pending requests finish. Sending requires being out of combat. The chatbot requires the local runtime and a working provider connection; its answers are generated content and are not part of this offline manual."], page = "Chatbot" },
}, modules = {
    ["Chatbot"] = L["Ask the local AI assistant about your character and selected quests; choose a provider and model, send with reload, then check replies after the local runtime finishes."],
    ["ActionBars"] = L["Style action buttons, keybind and macro text, range feedback and mouseover fading."],
