    ["Contexts"] = L["Set rules that choose profiles for your current content, role and group."],
    ["Cooldowns"] = L["Customize countdown numbers, cooldown animations and pulse feedback."],
    ["DataBars"] = L["Configure experience and reputation bars, text, size and visibility."],
    ["Diagnostics"] = L["Inspect compatibility, conflicts and captured errors; generate a report and review offered repairs."],
